-- Mod-authored natural wonder portrait descriptions, fr_FR overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Aucune description pour cette merveille naturelle."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Un vaste cratère d'impact vu depuis son rebord, une cuvette déchiquetée enfoncée dans un sol désertique pâle. La pente proche est couverte d'une broussaille verte qui plonge dans la fosse ombragée, dont le fond repose dans une obscurité brun foncé, et le rebord lointain s'élève en bandes de beige et d'or sous un ciel voilé."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Une pyramide à degrés en or massif, dont un escalier abrupt gravit la face jusqu'à un petit sanctuaire au sommet. De gigantesques lingots d'or sont empilés à sa base parmi des arbres sombres et élancés, et toute la scène rayonne de jaune, le trésor de la cité mythique rendu littéral. Les rayons de lumière derrière elle évoquent un lever de soleil perçant au-dessus de la cité perdue."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Une source d'une eau turquoise d'un éclat impossible jaillit d'un bassin perché au sommet de sombres falaises rocheuses et se déverse en une cascade lumineuse dans le bassin en contrebas. Des touffes d'herbe verte s'accrochent à la roche noire, des frondes de palmier encadrent un ciel doré et chaud, et de minuscules scintillements dans l'eau la désignent comme magique plutôt que naturelle."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Un cône volcanique parfait emplit le cadre, sa large calotte de neige descendant presque jusqu'au bas des pentes. La neige est peinte en blanc doux et bleu pâle sur un ciel bleu profond, et une bande de broussaille verte et d'eau brumeuse s'étend au pied de la montagne."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Un geyser jaillit d'un monticule pâle et rocailleux, sa gerbe blanche s'évasant pour emplir tout le ciel d'une brume sur le bleu. Une sombre forêt de conifères se referme des deux côtés, et le premier plan est une croûte de terrasses minérales en beige, ocre et brun."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Un grand promontoire calcaire s'élève d'une mer plate, des falaises pâles et abruptes sur sa face gauche et une longue pente de végétation vert foncé dévalant son dos. Toute la scène est baignée d'or, le ciel et l'eau rayonnant comme en fin d'après-midi."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Un énorme dôme strié de neige emplit la moitié supérieure du cadre en blanc et bleu glacés, une couronne de petits nuages dérivant à sa base. En dessous s'étend une savane verte où deux girafes se tiennent près d'un point d'eau pâle, des arbres à la cime aplatie aux bords de la scène."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Un large lac turquoise s'étend jusqu'à des collines pâles à l'horizon, encadré par des affleurements rocheux beiges de part et d'autre. Au centre du premier plan, un hippopotame émerge, sa tête et son dos brisant l'eau ridée, sous une lueur blanche qui emplit le ciel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Une mesa à la cime aplatie, faite de roche stratifiée rouge orangé, s'élève seule au-dessus d'une plaine aride, des parois de falaise zébrées surplombant de longues pentes d'éboulis. Une broussaille verte clairsemée parsème le sol sablonneux à son pied, et le sommet plat tranche d'une ligne dure sur un ciel d'un bleu vif."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Une pyramide de roche striée et de neige s'élève sur un ciel bleu profond, sa face rayée éclairée d'un or chaud sur un côté. En dessous, le premier plan n'est que rude champ de neige et crêtes de glace dans une ombre bleu froid."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Un groupe de pics désertiques rocailleux en grès brun orangé, de profonds ravins entaillant leurs faces, avec une douce lueur de lumière perçant derrière le sommet central. Des rochers épars jonchent le replat sablonneux au premier plan sous un ciel bleu dégagé."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Une montagne nue d'un brun rougeâtre dont les pentes inférieures sont ensevelies sous des amas de rochers gris luisant de minerai d'argent. Un sentier serpente sur son flanc, des rangées de blocs sombres équarris bordent sa base à la manière de galeries de mine, et le sommet poussiéreux se dresse sur un ciel bleu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Une scène sous-marine : le corail envahit la gauche et le bas du cadre en orange, rouge, violet et bleu pâle, des éponges tubulaires se dressant droites parmi les ramifications. De petits poissons tropicaux dérivent dans l'eau bleu profond, un jaune vif au centre. La lumière s'estompe vers une obscurité ouverte en haut à droite."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Une porterie monumentale tenant lieu des mines légendaires : une haute muraille de forteresse sombre couronnée de créneaux à pointe d'or, une entrée en son centre, flanquée de tours de pierre beige. Devant elle, le sol de roche pâle est sculpté en courbes amples, comme si le sol lui-même avait été extrait et poli."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Une montagne d'un vert luxuriant s'élève jusqu'à un pic arrondi, la jungle couvrant ses pentes sauf là où la roche brun orangé affleure en falaises. De hauts brins d'herbe parsemés de petites fleurs bleues emplissent le premier plan, et le ciel derrière est d'un turquoise tropical éclatant."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Un grand monolithe rouge s'étend à mi-distance, sa masse arrondie de grès sillonnée de rainures verticales et rougeoyant d'orange dans la lumière. Devant lui s'étend une broussaille plate de l'outback, une terre rouge tachetée de basse végétation verte et de touffes d'herbe, sous un ciel d'un bleu vif."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Un sombre cône volcanique s'élève de la mer au-delà d'une bande d'eau turquoise pâle, vu depuis un rivage de jungle dont les larges feuilles vertes encadrent la scène. Le ciel au-dessus brûle d'un jaune sulfureux, avec une faible volute de fumée au-dessus du sommet laissant présager l'éruption à venir."
